style.css:
@-moz-document domain("google.com") {
body, html {
    background-color: #ffe6f0 !important;
    color: #660033 !important;
  }

  input, textarea, select {
    background-color: #fff0f5 !important;
    color: #660033 !important;
    border: 1px solid #ff99cc !important;
  }

  a {
    color: #cc007a !important;
  }

  .g, .rc, .r, .s {
    background-color: #ffe6f0 !important;
    border-radius: 10px;
    padding: 5px;
  }

  #searchform, #main, #footer {
    background-color: #ffe6f0 !important;
  }

  .sfbg {
    background-color: #ffccdd !important;
  }

  .logo img {
    filter: hue-rotate(300deg) saturate(1.5);
  }
}
